def transform(grid):
    # The 6-background field is the canvas; encode each 3x3 unit using
    # the repeated marker pattern centered on each original 4/5 feature.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each input cell is transformed according to periodic 3x3 stencil
    # anchored to repeated 4-valued sparse pattern.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 4:
                out[r][c] = 5
            elif v == 5:
                out[r][c] = 9
            else:
                out[r][c] = 6
    return out

