   "newText": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The sparse 8s mark anchors where the nearby object is copied upward.
    # Identify the non-background object as a connected component and translate
    # it so its top-left aligns with each isolated 8 marker.
    bg = grid[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x,grid[y][x]))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]!=bg:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append(comp)
    if not objects:
        return out
    # largest component is the exemplar; isolated background-color exclusions are anchors
    shape=max(objects,key=len)
    minr=min(r for r,c,v in shape); minc=min(c for r,c,v in shape)
    rel=[(r-minr,c-minc,v) for r,c,v in shape]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and all(abs(r-rr)+abs(c-cc)>1 for rr,cc,_ in shape):
                for dr,dc,v in rel:
