{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-2/play/users/u019/system/state/workspace/programs/task-a1582562.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    colors = {v for row in grid for v in row if v != bg}
    out = [row[:] for row in grid]
    if not colors:
        return out
    # The anchor color is the color forming multiple isolated single-cell
    # markers; all other foreground cells make the exemplar to replicate.
    counts = {v: sum(row.count(v) for row in grid) for v in colors}
    anchor_color = min(colors, key=lambda v: (counts[v], v))
    exemplar = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                if grid[r][c] not in (bg, anchor_color)]
    if not exemplar:
        return out
    minr = min(r for r, c, v in exemplar)
    maxr = max(r for r, c, v in exemplar)
    minc = min(c for r, c, v in exemplar)
    maxc = max(c for r, c, v in exemplar)
    cr, cc = (minr + maxr) // 2, (minc + maxc) // 2
    shape = [(r-cr, c-cc, v) for r, c, v in exemplar]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == anchor_color:
                for dr, dc, v in shape:
                    rr, col = r+dr, c+dc
                    if 0 <= rr < h and 0 <= col < w:
                        out[rr][col] = v
    return out
